// === Tab: mySketch.js ===
/* 
 * A fork of tp5_250806_StaircaseWaterway
 * Modified: Deep midnight blue palette & glowing golden stars
 * Feature: Auto-cleanup off-screen particles
 */

let particles = [];
let time = 0;

function setup() {
	createCanvas(720, 720);
	noStroke();
}

function draw() {
	// 1. 高级墨夜深蓝背景（保留拖尾）
	background(52, 174, 235, 25);
	filter(BLUR);

	/* ---- 粒子生成：使用 push 压入数组 ---- */
	let i = 9;
	while (i > 0) {
		i--;

		let px = (time * 50) % width;
		let obj = {
			x: px,
			y: 0,
			g: 0, 
			s: 3.5 // 星星初始大小
		};

		particles.push(obj);
		time = time + 1;
	}

	/* ---- 粒子更新与清理循环（倒序遍历） ---- */
	for (let idx = particles.length - 1; idx >= 0; idx--) {
		let p = particles[idx];

		// 星星随时间缩减
		p.s = p.s * 0.997;

		let Noise = noise(p.x / width, p.y / 9, time / width);

		// 水平阶梯滑移
		if (Noise > 0.4) {
			p.x += 0;
		} else {
			if (Noise % 0.1 > 0.05) {
				p.x += 1;
			} else {
				p.x += -1;
			}
			p.g = 0;
		}

		// 垂直加速/平移
		if (Noise > 0.4) {
			p.g += 0.5;
			p.y += p.g;
		} else {
			p.y += 0.5;
		}

		// ★【核心清理判断】
		// 如果小星星落出屏幕底部（或缩减至几乎不可见），直接从数组中移除
		if (p.y > height + 10 || p.s < 0.2) {
			particles.splice(idx, 1);
			continue; // 已经删除，跳过本次绘制
		}

		// 绘制黄色小星星
		fill(255, 225, 120, 220);
		noStroke();
		drawStar(p.x, p.y, p.s, p.s * 0.45, 5);
	}
}

/**
 * 绘制五角星辅助函数
 */
function drawStar(x, y, radius1, radius2, npoints) {
	let angle = TWO_PI / npoints;
	let halfAngle = angle / 2.0;

	beginShape();
	for (let a = -HALF_PI; a < TWO_PI - HALF_PI; a += angle) {
		let sx = x + cos(a) * radius1;
		let sy = y + sin(a) * radius1;
		vertex(sx, sy);
		sx = x + cos(a + halfAngle) * radius2;
		sy = y + sin(a + halfAngle) * radius2;
		vertex(sx, sy);
	}
	endShape(CLOSE);
}

